class EventArgs:
    """Event data passed to handlers: X, Y, Button, Delta, KeyCode, KeyChar, Cancel."""

    def __init__(self, ev=None):
        self.raw = ev
        self.X = self.Y = self.Delta = 0
        self.Button = 0
        self.KeyCode = 0
        self.KeyChar = ""
        self.Cancel = False
        if ev is None:
            return
        if hasattr(ev, "position"):
            p = ev.position()
            self.X, self.Y = int(p.x()), int(p.y())
        if hasattr(ev, "button"):
            self.Button = {Qt.MouseButton.LeftButton: 1, Qt.MouseButton.MiddleButton: 2,
                           Qt.MouseButton.RightButton: 3}.get(ev.button(), 0)
        if hasattr(ev, "angleDelta"):
            self.Delta = ev.angleDelta().y()
        if hasattr(ev, "key"):
            self.KeyCode = ev.key()
            self.KeyChar = ev.text()


class _Events(QObject):
    """Event filter that routes Qt events to VB-style handlers."""

    def __init__(self, owner, widget, table):
        super().__init__(widget)
        self.owner, self.table = owner, table      # {QEvent.Type: [(handler, kind, chars_only)]}
        widget.installEventFilter(self)

    def eventFilter(self, obj, ev):
        for name, kind, chars in self.table.get(ev.type(), ()):
            if chars and not ev.text():
                continue
            fn = getattr(self.owner, name, None)
            if fn is not None:
                fn(EventArgs(ev)) if kind else fn()
        return False

class _Layout(QObject):
    """Anchor / Dock: re-places the children of *host* whenever it is resized.
    spec = (x, y, w, h, rx, ry, rw, rh): x = x0 + rx * host width, width = w0 + rw * host width..."""

    def __init__(self, host):
        super().__init__(host)
        self.host, self.items = host, []
        host.installEventFilter(self)

    def eventFilter(self, obj, ev):
        if obj is self.host and ev.type() == QEvent.Type.Resize:
            self.apply()
        return False

    def apply(self):
        cw, ch = self.host.width(), self.host.height()
        for w, (x, y, ww, hh, rx, ry, rw, rh) in self.items:
            g = [round(x + rx * cw), round(y + ry * ch), max(0, round(ww + rw * cw)), max(0, round(hh + rh * ch))]
            held = getattr(w, "_rad_held", None)    # geometry a visual state / storyboard is animating
            if held:
                for i, (prop, cur) in enumerate((("Left", w.x()), ("Top", w.y()), ("Width", w.width()),
                                                 ("Height", w.height()))):
                    if prop in held:
                        g[i] = cur
            w.setGeometry(*g)


def _place(widget, host, spec):
    lay = host.findChild(_Layout, "", Qt.FindChildOption.FindDirectChildrenOnly)
    if lay is None:
        lay = _Layout(host)
    lay.items.append((widget, spec))




def _rad_languages(form, embedded):
    """Languages of a form: the embedded tables + <form>.<lang>.resx.json files next to the program."""
    import glob
    out = list(embedded)
    here = os.path.dirname(os.path.abspath(__file__))
    for p in glob.glob(os.path.join(here, form + ".*.resx.json")):
        code = os.path.basename(p)[len(form) + 1:-len(".resx.json")]
        if code and code not in out:
            out.append(code)
    return out


def _rad_pick_language(available):
    """RADIDE_LANG, else language.txt next to the program, else the user's UI language ("" = default)."""
    import locale
    want = os.environ.get("RADIDE_LANG", "").strip()
    if not want:
        try:
            here = os.path.dirname(os.path.abspath(__file__))
            with open(os.path.join(here, "language.txt"), encoding="utf-8") as f:
                want = f.read().strip()
        except OSError:
            want = ""
    if not want:
        try:
            import ctypes
            want = locale.windows_locale.get(ctypes.windll.kernel32.GetUserDefaultUILanguage(), "")
        except (AttributeError, OSError, ImportError):
            want = ""
    if not want:
        try:
            want = locale.getlocale()[0] or os.environ.get("LANG", "")
        except ValueError:
            want = os.environ.get("LANG", "")
    want = want.split(".")[0].replace("-", "_").lower()
    if want in ("", "default", "(default)"):
        return ""
    low = {a.lower().replace("-", "_"): a for a in available}
    if want in low:
        return low[want]
    return low.get(want.split("_")[0], "")


def _rad_resources(form, lang, embedded):
    """The table of *lang*: embedded + <form>.<lang>.resx.json next to the program (None = no such language)."""
    if not lang:
        return None
    res = None
    if lang in embedded:
        res = dict(embedded[lang])
        res["strings"] = dict(res.get("strings") or {})
    try:
        import json
        here = os.path.dirname(os.path.abspath(__file__))
        with open(os.path.join(here, f"{form}.{lang}.resx.json"), encoding="utf-8") as f:
            ext = json.load(f)
        res = res or {"strings": {}}
        res["strings"].update(ext.get("strings") or {})
        for k in ("RightToLeft", "RightToLeftLayout"):
            if k in ext:
                res[k] = bool(ext[k])
    except (OSError, ValueError, AttributeError):
        pass
    return res


class _RadMirror(QObject):
    """Mirrored (right-to-left) placement of children that have no Anchor / Dock layout."""

    def __init__(self, host):
        super().__init__(host)
        self.host, self.items = host, []
        host.installEventFilter(self)

    def eventFilter(self, obj, ev):
        if obj is self.host and ev.type() == QEvent.Type.Resize:
            self.apply()
        return False

    def apply(self):
        cw, ch = self.host.width(), self.host.height()
        for w, (x, y, ww, hh, rx, ry, rw, rh) in self.items:
            w.setGeometry(round(x + rx * cw), round(y + ry * ch), max(0, round(ww + rw * cw)),
                          max(0, round(hh + rh * ch)))

